void SQLServerNewDB::OnPane(wxCommandEvent &WXUNUSED(event))  // wxGlade: SQLServerNewDB.<event_handler>
{
    switch( m_panes->GetSelection() )
    {
    case 0:
        m_mainPanel1->Show();
        m_mainPanel2->Hide();
        m_mainPanel3->Hide();
        m_dbName->SetFocus();
        break;
    case 1:
        m_mainPanel1->Hide();
        m_mainPanel2->Show();
        m_mainPanel3->Hide();
        break;
    case 2:
        m_mainPanel1->Hide();
        m_mainPanel2->Hide();
        m_mainPanel3->Show();
        break;
    }
    Layout();
}


// wxGlade: add SQLServerNewDB event handlers

void SQLServerNewDB::OnCellLeftClick(wxGridEvent &event)
{
    CallAfter( [this, row = event.GetRow(), col = event.GetCol() ] ()
    {
        if( !this->m_files->IsReadOnly( row, col ) && this->m_files->CanEnableCellControl() )
        {
            this->m_files->EnableCellEditControl( true );
        }
    } );
    event.Skip();
}

void SQLServerNewDB::OnEnteringDBName(wxCommandEvent &event)
{
    auto value = m_dbName->GetValue();
    m_files->SetCellValue( 0, 0, value );
    auto logValue = m_files->GetCellValue( 1, 0 );
    logValue = value + logValue;
    m_files->SetCellValue( 1, 0, logValue );
}

